const body = $json.body || $json;
const journalId = parseInt(body.journal_id, 10);
const transactions = Array.isArray(body.transactions) ? body.transactions : [];

if (!journalId) {
  return [{ json: { is_valid: false, error_message: 'Falta journal_id (id del diario bancario en Odoo, account.journal tipo bank).' } }];
}
if (transactions.length === 0) {
  return [{ json: { is_valid: false, error_message: 'transactions debe ser un array con al menos 1 movimiento.' } }];
}
for (const [i, t] of transactions.entries()) {
  if (!t.date || typeof t.amount === 'undefined' || !t.description) {
    return [{ json: { is_valid: false, error_message: `Transaccion #${i + 1} incompleta: requiere date, amount y description.` } }];
  }
}

return [{
  json: {
    is_valid: true,
    journal_id: journalId,
    transactions,
    odoo_db: $env.ODOO_DB,
    odoo_user: $env.ODOO_USER,
    odoo_password: $env.ODOO_PASSWORD
  }
}];

const err = $input.first().json;
const detalle = err.error?.message ?? err.message ?? JSON.stringify(err);
return [{ json: { text: `🔴 <b>Conciliacion Bancaria: fallo al autenticar contra Odoo</b>\nDetalle: <code>${detalle}</code>` } }];

const ctx = $('Validar Payload').first().json;
const uid = $json.result;
return ctx.transactions.map(t => ({
  json: {
    date: String(t.date).slice(0, 10),
    amount: Number(t.amount),
    description: String(t.description),
    reference: t.reference ? String(t.reference) : '',
    partner_hint: t.partner_hint ? String(t.partner_hint) : '',
    journal_id: ctx.journal_id,
    odoo_uid: uid,
    odoo_db: ctx.odoo_db,
    odoo_password: ctx.odoo_password
  }
}));

const tx = $('Expandir Transacciones').item.json;
const lineId = $json.result;
const amount = Math.abs(tx.amount);
const tolerance = Math.max(amount * 0.02, 1);
const moveTypes = tx.amount > 0 ? ['out_invoice', 'out_refund'] : ['in_invoice', 'in_refund'];
const domain = [
  ['state', '=', 'posted'],
  ['payment_state', 'in', ['not_paid', 'partial']],
  ['move_type', 'in', moveTypes],
  ['amount_residual', '>=', amount - tolerance],
  ['amount_residual', '<=', amount + tolerance]
];
if (tx.partner_hint) {
  domain.push(['partner_id.name', 'ilike', tx.partner_hint]);
}
return [{ json: { ...tx, line_id: lineId, search_domain: JSON.stringify(domain) } }];

const ctx = $('Preparar Busqueda Candidatos').item.json;
const candidates = $json.result || [];
let matchQuality;
if (candidates.length === 0) matchQuality = 'sin_match';
else if (candidates.length === 1) matchQuality = 'match_unico';
else if (candidates.length >= 20) matchQuality = 'demasiados_candidatos';
else matchQuality = 'multiples_candidatos';

return [{
  json: {
    description: ctx.description,
    amount: ctx.amount,
    date: ctx.date,
    line_id: ctx.line_id,
    match_quality: matchQuality,
    candidates: candidates.slice(0, 5).map(c => ({ id: c.id, name: c.name, partner: c.partner_id?.[1] ?? 'N/D', residual: c.amount_residual }))
  }
}];

const items = $input.all().map(i => i.json);
const sinMatch = items.filter(i => i.match_quality === 'sin_match');
const matchUnico = items.filter(i => i.match_quality === 'match_unico');
const multiples = items.filter(i => i.match_quality === 'multiples_candidatos' || i.match_quality === 'demasiados_candidatos');

let text = `💱 <b>Conciliacion Bancaria</b>\n<b>${items.length}</b> movimiento(s) importado(s) a Odoo (lineas creadas y contabilizadas).\n\n`;
text += `✅ <b>${matchUnico.length}</b> con match unico sugerido\n`;
text += `⚠️ <b>${multiples.length}</b> con multiples candidatos (revisar manualmente)\n`;
text += `❔ <b>${sinMatch.length}</b> sin ninguna factura abierta que coincida\n`;

if (matchUnico.length > 0) {
  text += `\n<b>Matches sugeridos:</b>\n`;
  for (const m of matchUnico.slice(0, 10)) {
    const c = m.candidates[0];
    text += `• ${m.description} ($${m.amount}) ➔ <code>${c.name}</code> (${c.partner}, residual $${c.residual})\n`;
  }
}
if (sinMatch.length > 0) {
  text += `\n<b>Sin match (requieren alta manual o son gastos no facturados):</b>\n`;
  for (const m of sinMatch.slice(0, 10)) {
    text += `• ${m.description} ($${m.amount})\n`;
  }
}
text += `\n<i>Ningun movimiento se concilio automaticamente — todas las sugerencias requieren confirmacion manual en Odoo antes de aplicarse.</i>`;

return [{ json: { text, total: items.length, sin_match: sinMatch.length, match_unico: matchUnico.length, multiples: multiples.length } }];
